const upsertRunRequest = `-- name: UpsertRunRequest :exec
INSERT INTO agents.run_queue (role_id, conversation_id, reason, note, not_before, due_by, created_at)
VALUES ($1, $2, $3, $4, $5::timestamptz, $6::timestamptz, $7::timestamptz)
ON CONFLICT (role_id, conversation_id, subject_id) WHERE taken_at IS NULL
DO UPDATE SET not_before = LEAST(EXCLUDED.not_before, agents.run_queue.due_by),
              note = CASE
                  -- Two mentions before the run: the run reads both notes.
                  WHEN EXCLUDED.note LIKE 'mention:%' AND agents.run_queue.note LIKE 'mention:%'
                      THEN agents.run_queue.note || ',' || substr(EXCLUDED.note, 9)
                  WHEN EXCLUDED.note <> '' THEN EXCLUDED.note
                  ELSE agents.run_queue.note END
`

type UpsertRunRequestParams struct {
	RoleID         uuid.UUID
	ConversationID uuid.UUID
	Reason         string
	Note           string
	NotBefore      time.Time
	DueBy          time.Time
	Now            time.Time
}

// One untaken request per (role, conversation): a second message moves
// not_before to now + the wait, never past due_by (first + the ceiling).
func (q *Queries) UpsertRunRequest(ctx context.Context, arg UpsertRunRequestParams) error {
	_, err := q.db.Exec(ctx, upsertRunRequest,
		arg.RoleID,
		arg.ConversationID,
		arg.Reason,
		arg.Note,
		arg.NotBefore,
		arg.DueBy,
		arg.Now,
	)
	return err
}

